try:
    import gmpy2
    HAVE_GMP = True
except ImportError:
    HAVE_GMP = False

try:
    from Crypto.Util import number
    HAVE_CRYPTO = True
except ImportError:
    HAVE_CRYPTO = False

# GMP's powmod has greater overhead than Python's pow(b, e, m), but is
# faster for huge exponents/moduli.
POW_MOD_GMP_SIZE = (2 ** 256) if HAVE_GMP else 0


def powmod(a, b, c):
    """Uses GMP, if available, to do a^b mod c where a, b, c are integers.

    :return int: (a ** b) % c
    """
    if a == 1:
        return 1
    if HAVE_GMP and (a >= POW_MOD_GMP_SIZE or
                     b >= POW_MOD_GMP_SIZE or
                     c >= POW_MOD_GMP_SIZE):
        # If a, b, and c are of similar size, gmpy2's powmod is faster.
        return int(gmpy2.powmod(a, b, c))
    else:
        return pow(a, b, c)


def mulmod(a, b, c):
    """Return a*b % c."""
    return (a * b) % c


def invert(a, b):
    """The multiplicitive inverse of a in the integers modulo b.

    :return int: x, where a * x == 1 mod b
    """
    if HAVE_GMP:
        return int(gmpy2.invert(a, b))
    else:
        _, s, _ = extended_euclidean_algorithm(a, b)
        return s % b


def getprimeover(N):
    """Return a random N-bit prime number

    Use the cryptographically secure getPrime from pycrypto when available,
    otherwise use a modified version of the rabin-miller prime tester.
    """
    if HAVE_CRYPTO:
        return number.getPrime(N)
    else:
        randfunc = random.SystemRandom()
        while True:
            n = randfunc.getrandbits(N)
            # Ensure the prime is exactly N bits long
            n |= (1 << (N - 1)) | 1
            if is_prime(n):
                return n


def isqrt(n):
    """Integer square root. Uses math.isqrt where available."""
    return math.isqrt(n)


def improved_i_sqrt(n):
    """ taken from
    http://stackoverflow.com/questions/15390807/integer-square-root-in-python
    :param n:
    :return:
    """
    assert n >= 0
    if n == 0:
        return 0
    i = n.bit_length() >> 1    # i = floor( (1/2) * n.bit_length() )
    m = 1 << i    # m = 2^i
    #
    # Fact: (2^(i + 1))^2 > n, so m has at least as many bits as floor(sqrt(n))
    #
    # Proof: (2^(i+1))^2 = 2^(2i + 2) >= 2^(floor(n.bit_length() / 2) * 2 + 2)
    # >= 2^(n.bit_length() + 1) > 2^(n.bit_length()) >= n since
    # n >= 2^(n.bit_length())
    #
    # (2^(i+1))^2 > 2^(n.bit_length()) >= n
    #
    # note: (2^(i+1))^2 = 2^(2i + 2), since (i+1) is an integer, 2i+2 is an
    # even integer, so 2^(2i+2) is a perfect square.
    while m * m > n:
        i -= 1
        m = 1 << i
    for k in range(i - 1, -1, -1):
        x = m | (1 << k)
        if x * x <= n:
            m = x
    return m


def extended_euclidean_algorithm(a, b):
    """Extended Euclidean algorithm.

    Returns (gcd, s, t) such that gcd = s*a + t*b.
    """
    s, old_s = 0, 1
    t, old_t = 1, 0
    r, old_r = b, a
    while r != 0:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s
        old_t, t = t, old_t - quotient * t
    return old_r, old_s, old_t


def miller_rabin(n, a):
    """Miller-Rabin primality test with base a.

    :param n: odd integer to test for primality
    :param a: witness
    :returns: False if n is definitely composite, True if possibly prime
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # Write n - 1 as 2^r * d with d odd
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d >>= 1
    x = powmod(a, d, n)
    if x == 1 or x == n - 1:
        return True
    for _ in range(r - 1):
        x = powmod(x, 2, n)
        if x == n - 1:
            return True
    return False


def is_prime(n, mr_rounds=25):
    """Test primality of n.

    First trial divides by the first few primes, then uses the Miller-Rabin
    probabilistic primality test with the given number of rounds.
    """
    if n < 2:
        return False
    for prime in first_primes:
        if n == prime:
            return True
        if n % prime == 0:
            return False
    rand = random.SystemRandom()
    for _ in range(mr_rounds):
        a = rand.randrange(2, n - 1)
        if not miller_rabin(n, a):
            return False
    return True


def int_to_base64(a):
    """Encode a non-negative integer as a base64 string.

    Uses the minimal big-endian byte representation of the integer.

    :param int a: positive integer to encode
    :returns: base64 encoded string
    """
    assert a > 0, "Must encode a positive integer"
    # Minimal number of bytes to represent a
    byte_length = (a.bit_length() + 7) // 8
    byte_repr = a.to_bytes(byte_length, byteorder='big')
    return base64.b64encode(byte_repr).decode('utf-8')


def base64_to_int(s):
    """Decode a base64 string to an integer (big-endian)."""
    return int.from_bytes(base64.b64decode(s), byteorder='big')


def base64url_encode(data):
    """URL-safe base64 encoding without padding of a bytes object."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')


def base64url_decode(s):
    """Decode a URL-safe base64 string (padding is added back if needed)."""
    if isinstance(s, str):
        s = s.encode('utf-8')
    # Restore padding
    s += b'=' * (-len(s) % 4)
    return base64.urlsafe_b64decode(s)


def _sieve_of_eratosthenes(limit):
    """Return all primes up to (and including) limit."""
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, prime in enumerate(sieve) if prime]


def _generate_first_primes(count=1000):
    """Generate the first `count` primes."""
    # By the prime number theorem, the nth prime is < n * (ln n + ln ln n)
    # for n >= 6. Use a sieve bound with a safety margin.
    if count < 6:
        limit = 20
    else:
        n = count
        limit = int(n * (math.log(n) + math.log(math.log(n)))) + 10
    primes = _sieve_of_eratosthenes(limit)
    while len(primes) < count:
        limit *= 2
        primes = _sieve_of_eratosthenes(limit)
    return primes[:count]


# The first 1000 primes, used for trial division in is_prime.
first_primes = _generate_first_primes(1000)

